-- TomoModForever 1.2.1 release notes.

TomoMod_RegisterLocale("enUS", {
    ["wn_121_bags"] = "New - Adventure > Bag space: an animated banner warns you when your bags are nearly full (90 % by default), at login so you sell before heading out, and when loot crosses the threshold. Free slots, grey items and their value; only regular bags count.",
    ["wn_121_trainer"] = "New - Adventure > Trainer reminder: on level up a small panel lists the spells waiting at your class trainer, with icon, name, rank, price and total. The list is read at each trainer visit and kept per character.",
    ["wn_121_codex"] = "New - Adventure > Dungeon codex (/codex): the 35 Forever dungeons, those for your level first, with the route for your faction step by step and a waypoint on the entrance.",
    ["wn_121_pet"] = "New - Unit frames > Pet: happiness icon for hunter pets (happy / content / unhappy) beside the pet health bar, movable, with the pet's diet on hover. /tm pethappy to diagnose.",
    ["wn_121_fixes"] = "Fixed - Group manager tab blocked in combat, and reputation bar / fast loot options that stopped applying.",
})

